INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload)
SELECT 'core-2026-09-v4','unreal-subjunctive','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"unreal-subjunctive","title":"Unreal time and the subjunctive","level":"C1","order":65,"summary":"Recognise formal recommendations, imagined situations and expressions whose past form refers to the present.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["The mandative subjunctive","Negative subjunctives","Would rather and it is time","As if and hypothetical were"],"rules":[{"title":"The mandative subjunctive","explanation":"After a demand, recommendation or requirement, formal English can use a that-clause with the **base verb for every subject**. Be remains be. This pattern is especially common in American formal usage; British English also often uses should + base.","pattern":"They requested that she **be** present.","commonMistakes":["She be in a subjunctive clause is not an agreement error. The clause expresses a requirement rather than reporting a fact."],"examples":["Use the formal mandative subjunctive: “They recommend that she **prepare** the visitor guide today.”","Use the formal mandative subjunctive: “They recommend that she **restore** the old portrait today.”"],"skill":"form"},{"title":"Negative subjunctives","explanation":"In a mandative subjunctive, **not** normally comes directly before the base verb without do-support. The reporting verb may be past while the recommended action is later. The base verb does not backshift in the usual way.","pattern":"They insisted that he **not leave**.","commonMistakes":["The pattern differs from ordinary factual He does not leave. Read the demand or recommendation meaning first."],"examples":["Use a negative mandative subjunctive: “They insist that she **not prepare** the visitor guide without permission.”","Use a negative mandative subjunctive: “They insist that she **not restore** the old portrait without permission.”"],"skill":"meaning"},{"title":"Would rather and it is time","explanation":"Would rather + base verb expresses a preference about one’s own action. Would rather + subject + past form can express a preference about another person now or in the future. It is time + subject + past form says an action is overdue or due now.","pattern":"I’d rather **stay**. / I’d rather you **stayed**. / It’s time we **left**.","commonMistakes":["The past form in It’s time we left need not refer to a past departure."],"examples":["“I would rather **prepare** the visitor guide tomorrow.”","“I would rather **restore** the old portrait tomorrow.”"],"skill":"contrast"},{"title":"As if and hypothetical were","explanation":"As if or as though can compare a situation with an imagined one. A backshifted form can show that the speaker views it as unreal or doubtful. Were is common in formal hypothetical be clauses. Ordinary tenses remain possible when the comparison may be true.","pattern":"He speaks as if he **knew** everything.","commonMistakes":["As if does not automatically force unreal past; context can support an ordinary factual interpretation."],"examples":["The task is due now. Use the “it is time” past-form pattern: “It is time we **prepared** the visitor guide.”","The task is due now. Use the “it is time” past-form pattern: “It is time we **restored** the old portrait.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-unreal","dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"chapter":{"introduction":["Recognise formal recommendations, imagined situations and expressions whose past form refers to the present.","The form tells you how to build the sentence; the context tells you why that form is useful. Read each section with both questions in mind. The examples make one contrast at a time, while the practice mixes the skills so that you learn to recognise the pattern yourself."],"rules":[{"title":"The mandative subjunctive","explanation":"After a demand, recommendation or requirement, formal English can use a that-clause with the **base verb for every subject**. Be remains be. This pattern is especially common in American formal usage; British English also often uses should + base.","pattern":"They requested that she **be** present.","commonMistakes":["She be in a subjunctive clause is not an agreement error. The clause expresses a requirement rather than reporting a fact."],"examples":["Use the formal mandative subjunctive: “They recommend that she **prepare** the visitor guide today.”","Use the formal mandative subjunctive: “They recommend that she **restore** the old portrait today.”"],"skill":"form","id":"unreal-subjunctive-foundation-1","domain":"verbs","referenceIds":["bc-unreal","dfe-grammar"],"readingVersion":"core-2026-09-v3"},{"title":"Negative subjunctives","explanation":"In a mandative subjunctive, **not** normally comes directly before the base verb without do-support. The reporting verb may be past while the recommended action is later. The base verb does not backshift in the usual way.","pattern":"They insisted that he **not leave**.","commonMistakes":["The pattern differs from ordinary factual He does not leave. Read the demand or recommendation meaning first."],"examples":["Use a negative mandative subjunctive: “They insist that she **not prepare** the visitor guide without permission.”","Use a negative mandative subjunctive: “They insist that she **not restore** the old portrait without permission.”"],"skill":"meaning","id":"unreal-subjunctive-foundation-2","domain":"verbs","referenceIds":["bc-unreal","dfe-grammar"],"readingVersion":"core-2026-09-v3"},{"title":"Would rather and it is time","explanation":"Would rather + base verb expresses a preference about one’s own action. Would rather + subject + past form can express a preference about another person now or in the future. It is time + subject + past form says an action is overdue or due now.","pattern":"I’d rather **stay**. / I’d rather you **stayed**. / It’s time we **left**.","commonMistakes":["The past form in It’s time we left need not refer to a past departure."],"examples":["“I would rather **prepare** the visitor guide tomorrow.”","“I would rather **restore** the old portrait tomorrow.”"],"skill":"contrast","id":"unreal-subjunctive-foundation-3","domain":"verbs","referenceIds":["bc-unreal","dfe-grammar"],"readingVersion":"core-2026-09-v3"},{"title":"As if and hypothetical were","explanation":"As if or as though can compare a situation with an imagined one. A backshifted form can show that the speaker views it as unreal or doubtful. Were is common in formal hypothetical be clauses. Ordinary tenses remain possible when the comparison may be true.","pattern":"He speaks as if he **knew** everything.","commonMistakes":["As if does not automatically force unreal past; context can support an ordinary factual interpretation."],"examples":["The task is due now. Use the “it is time” past-form pattern: “It is time we **prepared** the visitor guide.”","The task is due now. Use the “it is time” past-form pattern: “It is time we **restored** the old portrait.”"],"skill":"application","id":"unreal-subjunctive-foundation-4","domain":"verbs","referenceIds":["bc-unreal","dfe-grammar"],"readingVersion":"core-2026-09-v3"},{"domain":"verbs","id":"indicative-imperative-subjunctive","title":"Mood: statements, directives and subjunctive patterns","explanation":"Mood concerns how a clause presents a proposition or directive. Ordinary indicative forms occur in statements and many questions. Imperatives give directives. The plain-form subjunctive appears after some demands, recommendations and formulaic expressions. Irrealis were marks remote hypothetical meaning. Terminology varies between teaching and descriptive grammars, so learn the construction as well as the label.","pattern":"They insist that he **be** present.","examples":["It is essential that she **not be** disturbed.","If I **were** in your position, I would ask."],"commonMistakes":["British English also often uses should in mandative clauses: They insist that he should be present. This is a standard alternative, not an error."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"verbs","id":"as-if-rather-and-formulae","title":"As if, would rather, it’s time and fixed subjunctives","explanation":"As if and as though compare an appearance with a situation; a past or past-perfect form can mark remoteness, while ordinary forms can leave the situation open. Would rather + a different subject often takes a past form for a present preference. Some subjunctives survive in fixed wishes or formal concessions.","pattern":"I’d rather **you stayed**.","examples":["He acts **as if he owned** the place.","**Be that as it may**, we still need a decision."],"commonMistakes":["As if does not always require unreal past: It looks as if it is going to rain presents an apparently likely situation."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["They requested that she **be** present.","They insisted that he **not leave**.","I’d rather **stay**. / I’d rather you **stayed**. / It’s time we **left**.","He speaks as if he **knew** everything."],"readingVersion":"core-2026-09-v4"},"stage":"6 · Advanced control","prerequisites":["ellipsis-substitution"],"readingReferenceIds":["bc-unreal","dfe-grammar","cambridge-comprehensive-scope"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='unreal-subjunctive'
